CREATE TABLE IF NOT EXISTS ownership_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, entity_type text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', registration_reference text, status text NOT NULL DEFAULT 'Active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, participant_type text NOT NULL, participant_name text NOT NULL, jurisdiction text, identifier_reference text, legal_ownership_percent numeric(12,6), beneficial_ownership_percent numeric(12,6), economic_participation_percent numeric(12,6), voting_percent numeric(12,6), ownership_basis text, verification_status text NOT NULL DEFAULT 'Unverified', protected_interest_flag boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_share_classes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, class_code text NOT NULL, class_name text NOT NULL, voting_rights text, economic_rights text, transfer_rules text, anti_dilution_rules text, reserved_rights text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_protections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, protection_code text NOT NULL, title text NOT NULL, protected_holder text, protection_type text NOT NULL, trigger_event text, protection_mechanism text NOT NULL, consent_required_from text, legal_instrument_reference text, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, transfer_type text NOT NULL, from_participant text, to_participant text, share_class text, quantity_or_percent text, transfer_date date, approval_route text, restrictions_check text, legal_review_status text NOT NULL DEFAULT 'Required', status text NOT NULL DEFAULT 'Proposed', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, event_type text NOT NULL, event_date date, participant_reference text, description text NOT NULL, prior_state text, resulting_state text, evidence_reference text, recorded_by text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_succession_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ownership_entity_id uuid REFERENCES ownership_entities(id) ON DELETE CASCADE, holder_reference text NOT NULL, trigger_event text NOT NULL, succession_route text NOT NULL, continuity_requirement text, dispute_route text, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS ownership_entity_id uuid;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS protection_code text;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS title text;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS consent_required_from text;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS protection_mechanism text;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS legal_instrument_reference text;
ALTER TABLE ownership_protections ADD COLUMN IF NOT EXISTS legal_review_required boolean NOT NULL DEFAULT true;
INSERT INTO ownership_entities(entity_name,entity_type,jurisdiction,notes) SELECT 'OSANVAULT AFRICA LTD','Parent / Group Entity','Nigeria','Ownership registry master record. Participant records are not populated until verified evidence is supplied.' WHERE NOT EXISTS (SELECT 1 FROM ownership_entities WHERE entity_name='OSANVAULT AFRICA LTD');
INSERT INTO ownership_share_classes(ownership_entity_id,class_code,class_name,voting_rights,economic_rights,transfer_rules,anti_dilution_rules,reserved_rights) SELECT id,'ORD','Ordinary Shares','To be confirmed against adopted articles and shareholder instruments.','To be confirmed.','Subject to applicable law and adopted transfer instruments.','To be legally defined if applicable.','None recorded yet.' FROM ownership_entities WHERE entity_name='OSANVAULT AFRICA LTD' AND NOT EXISTS (SELECT 1 FROM ownership_share_classes WHERE class_code='ORD');
INSERT INTO ownership_protections(entity_name,ownership_entity_id,protection_code,title,protection_title,protection_type,trigger_event,protection_mechanism,approval_requirement,consent_required_from,status) SELECT entity_name,id,'OP-01','Founding Interest Protection','Founding Interest Protection','Founding / constitutional','Proposed dilution, transfer or restructuring affecting a verified protected founding interest.','Route to reserved-matter review and applicable consent instrument; no automatic legal right is inferred by this record.','Enhanced governance review plus applicable legal instrument.','As specified in adopted legal instrument.','Proposed' FROM ownership_entities WHERE entity_name='OSANVAULT AFRICA LTD' AND NOT EXISTS (SELECT 1 FROM ownership_protections WHERE protection_code='OP-01');
INSERT INTO ownership_protections(entity_name,ownership_entity_id,protection_code,title,protection_title,protection_type,trigger_event,protection_mechanism,approval_requirement,consent_required_from,status) SELECT entity_name,id,'OP-02','Community / Indigenous Interest Protection','Community / Indigenous Interest Protection','Community / indigenous safeguard','Proposed transaction affecting a verified community, customary, ancestral or indigenous interest.','Require rights/evidence review, applicable consultation or consent and legal review before execution.','Rights/evidence review plus applicable governance approval.','Affected rights-holders where legally required.','Proposed' FROM ownership_entities WHERE entity_name='OSANVAULT AFRICA LTD' AND NOT EXISTS (SELECT 1 FROM ownership_protections WHERE protection_code='OP-02');